const a={title:"TripReel - Ücretsiz Seyahat Animasyon Uygulaması: Fotoğrafları Güzel Videolara Dönüştürün",description:"Animasyonlu haritalar ve uçuş rotalarıyla muhteşem seyahat videoları oluşturun. 3D küre rota haritalaması ile ücretsiz seyahat animasyon uygulaması. Fotoğraflarınızı otomatik olarak güzel seyahat videolarına dönüştürün. Gizlilik önce, çevrimdışı çalışır.",keywords:"seyahat animasyon uygulaması, seyahat haritası animasyon uygulaması, seyahat rotası animasyon uygulaması, uçuş animasyon uygulaması, seyahat video yapıcı, otomatik seyahat video, animasyonlu seyahat haritası, uçuş yolu animasyonu, seyahat animasyonu, küre animasyonu, seyahat özet video, fotoğraf video, seyahat öne çıkanlar, ücretsiz seyahat uygulaması, çevrimdışı video yapıcı, gizlilik seyahat uygulaması, kamera rulosu video"},e={logoAlt:"TripReel Logosu",appName:"TripReel",howItWorks:"Nasıl Çalışır",video:"Video",features:"Özellikler",theApp:"Uygulama"},i={badge:"Fotoğrafları Seyahat Hikayelerine Dönüştür",title1:"Kamera Rulonuz,",title2:"Tam Olarak Kullanılmış",description:"TripReel, fotoğraflarınızın konumlarından otomatik olarak güzel seyahat videoları oluşturur. Verileriniz gizli ve güvenli kalırken, 3D bir kürede çarpıcı animasyonlu rota haritaları ve uçuş yollarıyla yolculuklarınızın canlanmasını izleyin.",secure:"100% Güvenli",worksOffline:"Çevrimdışı Çalışır",globeAlt:"TripReel Küre Animasyonu"},l={title:"Nasıl Çalışır",subtitle:"Mükemmel seyahat videonuzu oluşturmak için üç basit adım",step1:{title:"Fotoğraf Erişimine İzin Ver",description:"TripReel'e fotoğraf kitaplığınıza erişim izni verin. Uygulama yalnızca konum meta verilerini okur, başka bir şey okumaz."},step2:{title:"Otomatik Seyahat Algılama",description:"TripReel, konum meta verilerini analiz eder ve tarih ve konumlara göre seyahatlerinizi akıllıca bulur."},step3:{title:"Videonuzu Oluşturun",description:"Yolculuğunuzun güzel bir küre animasyonunda nasıl açıldığını izleyin, sosyal medyada paylaşmaya hazır."}},r={title:"Sihrin Gerçekleşmesini Görün",subtitle:"TripReel'in fotoğraf kitaplığınızı harika seyahat videolarına nasıl dönüştürdüğünü izleyin",caption:"Nihai seyahat videonuz böyle görünebilir"},n={title:"İhtiyacınız Olan Her Şey",subtitle:"Modern gezginler için tasarlanmış güçlü özellikler",twoTap:{title:"İki Dokunuşla Seyahat Videoları",description:"Fotoğraf kitaplığınızdan sadece iki dokunuşla çarpıcı seyahat videoları oluşturun. Düzenleme gerektirmez."},smartTrip:{title:"Akıllı Seyahat Algılama",description:"Fotoğraflarınızdaki tarih ve konum meta verilerini analiz ederek seyahatlerinizi otomatik olarak bulur ve gruplar."},globe:{title:"Güzel Küre Animasyonu",description:"Dünyanın her yerindeki animasyonlu seyahat rotalarınızı ve uçuş yollarınızı gösteren çarpıcı bir 3D küre ile yolculuğunuzun canlanmasını izleyin."},privacy:{title:"Önce Gizlilik",description:"Her şey cihazınızda işlenir. Fotoğraflarınız asla telefonunuzu terk etmez. Uçak modunda çalışır."},customStyles:{title:"Özel Stiller",description:"Estetiğinize uyması ve her videoyu benzersiz kılmak için birden fazla dünya stili ve özelleştirmeler arasından seçim yapın."},manualControl:{title:"Manuel Kontrol",description:"Cihazınızda konum hizmetleri etkinleştirilmemişse tamamen yeni seyahatler manuel olarak ekleyebilirsiniz."}},t={title:"Yaratıcı Video Fikirleri",subtitle:"TripReel ile neler yaratabileceğinizden ilham alın. Hızlı hafta sonu kaçamakları den yıllık maceralara kadar, her yolculuk için çarpıcı seyahat videoları oluşturun.",description:"Bir seyahat haritası animasyonu oluşturuyor, bir uçuş rotasını belgeliyor veya yıl sonu seyahat özeti yapıyor olun, TripReel anılarınızı paylaşılabilir videolara dönüştürmeyi kolaylaştırır.",ideas:{yearRecap:{title:"2025 Seyahat Özeti",description:"2025 yıllık seyahat özet videonuzu otomatik olarak oluşturun"},europeRoadTrip:{title:"Avrupa Yol Gezisi",description:"Avrupa maceranızı animasyonlu rota haritalarıyla sergileyin"},southeastAsia:{title:"Güneydoğu Asya Yolculuğu",description:"Birden fazla ülkeyi kapsayan sırt çantası rotanızı görselleştirin"},japanRail:{title:"Japonya Tren Yolculuğu",description:"Japonya'daki tren rotalarınızın harita videolarını oluşturun"},crossCountry:{title:"ABD'yi Boydan Boya",description:"Amerikan yol gezinizi destansı bir rota videosuna dönüştürün"},islandHopping:{title:"Ada Turları",description:"Çarpıcı 3D animasyonlarla adadan adaya yolculuklarınızı gösterin"},worldTour:{title:"Dünya Turu Montajı",description:"Birden fazla seyahat tek bir harika küresel yolculuk videosunda"},travelPlans:{title:"2026 Seyahat Planları",description:"2026 için heyecan verici seyahat maceralarınızı görselleştirin ve planlayın"},lifetimeTravel:{title:"Ömür Boyu Seyahat Hikayesi",description:"Tüm hayat boyu seyahatlerinizi gösteren bir video oluşturun"},regionalExplorer:{title:"Bölgesel Kaşif",description:"Eyaletler, iller ve bölgeler boyunca maceralarınızı haritalandırın"},festivalCircuit:{title:"Festival Turu",description:"Müzik festivali ve etkinlik yolculuğunuzu haritalandırın"},bikeRoutes:{title:"Şehir Kaçamalarım",description:"Tüm şehir kaçamalarınızı sergileyin"}}},o={title:"Uygulama",subtitle:"Şimdi App Store'da mevcut",alt1:"Otomatik Seyahat Videoları - Saniyeler içinde çarpıcı videolar oluşturun",alt2:"Fotoğraf Konum Algılama - Fotoğraflarınızın meta verilerini kullanır",alt3:"Seyahat Algılama - Seyahatlerinizi otomatik olarak gruplar",alt4:"Güzel Dünya Videoları - Yolculuğunuzun küre animasyonu",alt5:"Özel Stiller - Seyahat videolarınızı kişiselleştirin"},u={comingSoon:"Yakında",androidTitle:"Android Uygulaması Yakında!",androidMessage:'Android sürümü henüz mevcut değil ancak yakında olacak. <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> adresine mesaj gönderin, hazır olduğunda size haber vereceğim!',gotIt:"Anladım!"},s={title:"Sıkça Sorulan Sorular",subtitle:"TripReel hakkında bilmeniz gereken her şey",q1:{question:"Uygulamayı uçak modunda tamamen kullanabilir miyim?",answer:"Evet! Premium kullanıcılar için uygulama, uçak modunda hiçbir sınırlama olmaksızın tamamen çevrimdışı olarak kullanılabilir. Premium olmayan kullanıcılar için bazı özellikler, geçici olarak interneti etkinleştirmeyi gerektirebilecek reklamlarla desteklenir, ancak premium kullanıcılar için reklam yoktur ve uygulama uçak modunda tamamen kullanılabilir."},q2:{question:"Premium'a yükselttim, filigranı nasıl kaldırabilirim?",answer:"Birçok kişi bu videoları oluşturmak için hangi uygulamanın kullanıldığını soruyor, bu yüzden premium'a yükselttikten sonra filigranın daha küçük bir versiyonunu ekleme (sadece uygulama adıyla) veya isterseniz tamamen kaldırma seçeneğiniz var."},q3:{question:"Fotoğraf verilerim güvenli ve gizli mi?",answer:"Kesinlikle! TripReel, fotoğraflarınızdan yalnızca konum meta verilerini okur - gerçek fotoğraf içeriğine asla erişmez, saklamaz veya iletmeyiz. Tüm işlemler cihazınızda yerel olarak gerçekleşir ve hiçbir veri asla telefonunuzdan çıkmaz. Uygulamayı uçak modunda kullanarak bunu doğrulayabilirsiniz - mükemmel şekilde çevrimdışı çalışır!"},q4:{question:"Fotoğraflarımda konum verileri yoksa ne olur?",answer:"Sorun değil! Fotoğraflarınızı çekerken konum hizmetleri etkinleştirilmemişse, manuel olarak seyahatler oluşturabilir ve kendiniz konumlar ekleyebilirsiniz. Uygulama size seyahat zaman çizelgenizi özelleştirmek için tam kontrol sağlar."},q5:{question:"Uygulama seyahatlerimi otomatik olarak nasıl algılıyor?",answer:"TripReel, ne zaman ve nereye seyahat ettiğinizi akıllıca belirlemek için fotoğraflarınızdaki konum meta verilerini ve zaman damgalarını analiz eder. Manuel çalışma gerektirmeden seyahatlerinizi otomatik olarak algılamak için yakın konumları ve tarihleri bir araya toplar."},q6:{question:"Videolarımın görünümünü özelleştirebilir miyim?",answer:"Evet! Kişisel estetiğinize uyması için birden fazla dünya stili arasından seçim yapabilir ve animasyonlu seyahat videolarınızın çeşitli yönlerini özelleştirebilirsiniz. Premium kullanıcılar ek rota animasyon stillerine, harita temalarına ve uçuş yolu seçeneklerine erişim kazanır."},q7:{question:"Hesap oluşturmam gerekiyor mu?",answer:"Hesap gerekmiyor! TripReel indirdikten hemen sonra çalışır. Kayıt yok, giriş yok ve kişisel bilgi gerekmez. Sadece uygulamayı indirin ve hemen seyahat videolarınızı oluşturmaya başlayın."},q8:{question:"Seyahatimden bir konum neden eksik?",answer:"Uygulama yalnızca mevcut verilerle çalışabilir, bu nedenle öncelikle o konumda en az birkaç fotoğrafa ihtiyacınız var. İkinci olarak, oradayken konum verilerinin etkinleştirildiğinden emin olmanız gerekir. Üçüncü olarak, bazen zayıf GPS alımı yanlış konum verilerine neden olabilir. Tüm bunları ekarte ettiyseniz ve konumunuz hala görünmüyorsa, Seyahatler Genel Bakış > Düzenle düğmesinden o konumu manuel olarak ekleyebilirsiniz. Lütfen sorunu bildirmek için İletişim'i de kullanın."},q9:{question:"Harika videomum nerede paylaşabilirim?",answer:"Elbette tüm sosyal platformlarda da paylaşabilirsiniz. Platforma daha iyi uyum sağlamak için uygulama, videolarınız için farklı en-boy oranlarına izin verir."},q10:{question:"Bir hatayı nerede bildirebilirim?",answer:"Sadece marian@qod.ee adresinden doğrudan benimle iletişime geçin ve sorunun ne olduğunu kısaca açıklayın."}},m={title:"E-posta Desteği",description:"Herhangi bir geri bildiriminiz varsa veya herhangi bir sorunla karşılaşırsanız, lütfen bu e-posta adresinden doğrudan benimle iletişime geçmekten çekinmeyin ve isteğinizi mümkün olduğunca hızlı bir şekilde kişisel olarak okuyacağım ve ele alacağım. Uygulamayı kullandığınız için teşekkürler!",close:"Kapat"},y={default:{title:"🍪 Çerezler",message:"Deneyiminizi geliştirmek için TripReel sitesinde çerezler kullanıyoruz. Kişisel veri toplanmaz.",accept:"Kabul Et",decline:"Reddet",details:"Detaylar"},theme:{title:"🍪 Çerezler",message:"🌙 Tema tercihinizi kaydetmek için TripReel sitesinde temel çerezleri kabul etmeniz gerekir. Bunlar olmadan tema seçiminiz kaydedilemez.",accept:"Kabul Et",decline:"Reddet",details:"Detaylar"}},k={privacy:"Uygulama Gizlilik Politikası",cookies:"Site Çerez Politikası",contact:"İletişim",cookiePreferences:"Çerez Tercihleri",madeWith:"İle yapıldı",forTravelers:"dünya çapındaki gezginler için",copyright:"© {{year}} TripReel."},d={title:"Yolculuğunuzu Paylaşmaya Hazır Mısınız?",description:"Bugün TripReel'i indirin ve kamera rulonuzu animasyonlu haritalar ve rotalarla güzel seyahat videolarına dönüştürün. Maceralarınız kutlanmayı hak ediyor.",features:"Ücretsiz indirme • Hızlı ve Kullanışlı • Gizlilik garantili"},z={meta:a,header:e,hero:i,howItWorks:l,videoSection:r,features:n,videoIdeas:t,screenshots:o,appStore:u,faq:s,contact:m,cookieBanner:y,footer:k,cta:d};export{u as appStore,m as contact,y as cookieBanner,d as cta,z as default,s as faq,n as features,k as footer,e as header,i as hero,l as howItWorks,a as meta,o as screenshots,t as videoIdeas,r as videoSection};
